28	/// A fully-assembled Bedrock Converse request, ready to send.
29	///
30	/// The fields map onto the Bedrock SDK `converse` / `converse_stream` input
31	/// parameters. Callers should inspect `synthesizing` to decide how to route
32	/// stream events (synthesized structured output → `TokenDelta` remapping).
33	#[derive(Debug)]
34	pub(crate) struct PreparedConverse {
35	    /// Bedrock model identifier (may include cross-region profile prefix).
36	    pub(crate) model_id: String,
37	    /// System prompt blocks.
38	    pub(crate) system: Vec<SystemContentBlock>,
39	    /// Conversation turns. Adjacent same-role turns are joined.
40	    pub(crate) messages: Vec<Message>,
41	    /// Tool configuration (tools list + optional tool_choice).
42	    pub(crate) tool_config: Option<ToolConfiguration>,
43	    /// Base inference parameters.
44	    pub(crate) inference_config: Option<InferenceConfiguration>,
45	    /// Whether the stream translator should remap the synthesized tool's
46	    /// output to `TokenDelta`.
47	    pub(crate) synthesizing: bool,
48	    /// Native structured-output configuration. Only the native path sets it.
49	    pub(crate) output_config: Option<OutputConfig>,
50	    /// The changes of meaning that the native path made to the request.
51	    /// The forced-tool path always leaves this empty.
52	    pub(crate) notices: Vec<NativeNotice>,
53	    /// Send the Anthropic `tool_choice: none` field in `additionalModelRequestFields`.
54	    pub(crate) tool_choice_none: bool,
55	}
56	
57	impl PreparedConverse {
58	    /// Returns `true` when the tool configuration forces a tool call
59	    /// (`toolChoice` is `any` or `tool`).
60	    pub(crate) fn has_forced_tool_choice(&self) -> bool {
61	        matches!(
62	            self.tool_config
63	                .as_ref()
64	                .and_then(ToolConfiguration::tool_choice),
65	            Some(BedrockToolChoice::Any(_) | BedrockToolChoice::Tool(_))
66	        )
67	    }
68	}
69	
70	/// The error for `ToolChoice::Required` when the tool list is empty.
71	fn required_without_tools_error() -> ModelError {
72	    ModelError::Other(anyhow::anyhow!(
73	        "ToolChoice::Required requires at least one tool to be defined",
74	    ))
75	}
76	
77	/// Make sure that `name` is the name of a tool in `tools`.
78	///
79	/// # Errors
80	/// Returns [`ModelError::Other`] when no tool in `tools` has the name `name`.
81	fn check_tool_name(tools: &[Tool], name: &str) -> Result<(), ModelError> {
82	    let defined = tools
83	        .iter()
84	        .any(|t| matches!(t, Tool::ToolSpec(spec) if spec.name() == name));
85	    if defined {
86	        Ok(())
87	    } else {
88	        Err(ModelError::Other(anyhow::anyhow!(
89	            "ToolChoice::Tool references tool {:?} which is not defined in the tool list",
90	            name,
91	        )))
92	    }
93	}
94	
95	/// Assemble the [`ToolConfiguration`] from the tool list and the optional tool choice.
96	///
97	/// Returns `None` when `tools` is empty. A `tool_choice` with no tools is then
98	/// omitted, because a `ToolConfiguration` needs at least one tool.
99	///
100	/// # Errors
101	/// Returns [`ModelError::Other`] when the SDK builder fails.
102	fn assemble_tool_config(
103	    tools: Vec<Tool>,
104	    tool_choice: Option<BedrockToolChoice>,
105	) -> Result<Option<ToolConfiguration>, ModelError> {
106	    if tools.is_empty() {
107	        if tool_choice.is_some() {
108	            tracing::debug!(
109	                target: "paigasus::bedrock::translate",
110	                "tool_choice requested but no tools provided; omitting ToolConfiguration",
111	            );
112	        }
113	        return Ok(None);
114	    }
115	    let mut builder = ToolConfiguration::builder();
116	    for t in tools {
117	        builder = builder.tools(t);
118	    }
119	    if let Some(tc) = tool_choice {
120	        builder = builder.tool_choice(tc);
121	    }
122	    Ok(Some(builder.build().map_err(|e| {
123	        ModelError::Other(anyhow::anyhow!("failed to build ToolConfiguration: {e}"))
124	    })?))
125	}
126	
127	/// Build an [`InferenceConfiguration`] from per-request settings and the builder config.
128	///
129	/// `maxTokens` is set only when the caller explicitly provided
130	/// `max_output_tokens` on the request or the builder was configured with
131	/// [`crate::BedrockModelBuilder::max_output_tokens_default`]. Omitting
132	/// `maxTokens` lets each Bedrock model apply its own correct default, which
133	/// avoids `ValidationException` on models whose limit is below any hardcoded
134	/// value.
135	///
136	/// Returns `None` when all three fields (temperature, top_p, max_tokens) are
137	/// absent — Bedrock accepts a missing `inferenceConfig` and all its fields are
138	/// individually optional.
139	fn build_inference_config(req: &ModelRequest, cfg: &Config) -> Option<InferenceConfiguration> {
140	    let max_tokens = req
141	        .model_settings
142	        .max_output_tokens
143	        .or(cfg.max_output_default);
144	
145	    // When no inference field is set, omit the config block entirely.
146	    if req.model_settings.temperature.is_none()
147	        && req.model_settings.top_p.is_none()
148	        && max_tokens.is_none()
149	    {
150	        return None;
151	    }
152	
153	    let mut b = InferenceConfiguration::builder();
154	    if let Some(t) = req.model_settings.temperature {
155	        b = b.temperature(t);
156	    }
157	    if let Some(p) = req.model_settings.top_p {
158	        b = b.top_p(p);
159	    }
160	    if let Some(mt) = max_tokens {
161	        b = b.max_tokens(mt as i32);
162	    }
163	    Some(b.build())
164	}
