166	/// Assemble a [`PreparedConverse`] from the builder `Config` and a [`ModelRequest`].
167	///
168	/// `path` selects the wire path. On [`OutputPath::Native`] the request goes to
169	/// the native builder, which sends structured output in `outputConfig` and
170	/// never forces a tool choice. The errors below are for
171	/// [`OutputPath::ForcedTool`].
172	///
173	/// # Errors
174	/// - Reserved tool name (`__paigasus_structured_output__` used by the caller).
175	/// - `ResponseFormat::JsonSchema`/`JsonObject` combined with `ToolChoice::Tool` (conflict).
176	/// - `ResponseFormat::JsonSchema`/`JsonObject` combined with `ToolChoice::None` (conflict).
177	/// - No message with content after empty/whitespace-only text is dropped.
178	/// - The last user message had only empty/whitespace-only text and the request would end with an assistant message.
179	pub(crate) fn build_request(
180	    cfg: &Config,
181	    req: &ModelRequest,
182	    path: OutputPath,
183	) -> Result<PreparedConverse, ModelError> {
184	    if path == OutputPath::Native {
185	        return native::build_native(cfg, req);
186	    }
187	    let family = cfg.family;
188	    let ruleset = Ruleset::for_family(family);
189	
190	    // Guard: ResponseFormat::JsonSchema / JsonObject + ToolChoice::Tool → conflict.
191	    let synthesizing_rf = matches!(
192	        req.model_settings.response_format.as_ref(),
193	        Some(paigasus_helikon_core::ResponseFormat::JsonSchema { .. })
194	            | Some(paigasus_helikon_core::ResponseFormat::JsonObject),
195	    );
196	    let forced_tool = matches!(
197	        req.model_settings.tool_choice.as_ref(),
198	        Some(ToolChoice::Tool { .. }),
199	    );
200	    if synthesizing_rf && family.supports_forced_tool_choice() && forced_tool {
201	        return Err(ModelError::Other(anyhow::anyhow!(
202	            "ResponseFormat::JsonSchema/JsonObject and ToolChoice::Tool are mutually \
203	             exclusive on Bedrock — use one or the other",
204	        )));
205	    }
206	
207	    // Guard: ResponseFormat::JsonSchema / JsonObject + ToolChoice::None → conflict.
208	    // With None the crate cannot force the synthesized tool, so the structured
209	    // format conflicts with None.
210	    let none_choice = matches!(
211	        req.model_settings.tool_choice.as_ref(),
212	        Some(ToolChoice::None),
213	    );
214	    if synthesizing_rf && family.supports_forced_tool_choice() && none_choice {
215	        return Err(ModelError::Other(anyhow::anyhow!(
216	            "ResponseFormat::JsonSchema/JsonObject and ToolChoice::None are mutually \
217	             exclusive on Bedrock — structured-output synthesis requires a tool call",
218	        )));
219	    }
220	
221	    // ToolChoice::None means the model MUST NOT call any tool this turn.
222	    // Without a tool round in the history, omit toolConfig entirely. With a
223	    // tool round, Converse needs a toolConfig, so the family strategy decides
224	    // (a none field for Anthropic models, a text history for the others).
225	    if none_choice {
226	        let translated = items_to_messages(&req.messages)?;
227	        let outcome = apply_tool_choice_none(translated.messages, &req.tools, family, ruleset)?;
228	        let tool_config = assemble_tool_config(outcome.tools, None)?;
229	        let inference_config = build_inference_config(req, cfg);
230	        return Ok(PreparedConverse {
231	            model_id: cfg.model_id.clone(),
232	            system: translated.system,
233	            messages: outcome.messages,
234	            tool_config,
235	            inference_config,
236	            synthesizing: false,
237	            output_config: None,
238	            notices: Vec::new(),
239	            tool_choice_none: outcome.tool_choice_none,
240	        });
241	    }
242	
243	    // Translate messages.
244	    let translated = items_to_messages(&req.messages)?;
245	
246	    // Translate user tool defs (also validates reserved name).
247	    let user_specs = tool_specs(&req.tools, ruleset)?;
248	
249	    // Synthesize structured output tool (if applicable).
250	    let Synthesized {
251	        tool: synth_tool,
252	        tool_choice: synth_tc,
253	        synthesizing,
254	    } = synthesize(req.model_settings.response_format.as_ref(), family, ruleset)?;
255	
256	    // Merge tool lists: user tools first, synthesized appended.
257	    let mut all_tools: Vec<Tool> = user_specs.into_iter().map(Tool::ToolSpec).collect();
258	    if let Some(st) = synth_tool {
259	        all_tools.push(Tool::ToolSpec(st));
260	    }
261	
262	    // Build ToolConfiguration (only when there are tools or a tool_choice).
263	    let caller_tc = req
264	        .model_settings
265	        .tool_choice
266	        .as_ref()
267	        .and_then(|tc| translate_tool_choice(tc, family));
268	
269	    // Synthesis overrides caller tool_choice.
270	    // synth_tool.is_some() always pushes to all_tools above, so a synthesized tool_choice is never silently dropped here.
271	    let effective_tc = synth_tc.or(caller_tc);
272	
273	    // Validate forced tool choices on supported families.
274	    // (On unsupported families, forced choices were already omitted by translate_tool_choice.)
275	    if family.supports_forced_tool_choice() {
276	        match req.model_settings.tool_choice.as_ref() {
277	            Some(ToolChoice::Required) if !synthesizing => {
278	                if all_tools.is_empty() {
279	                    return Err(required_without_tools_error());
280	                }
281	            }
282	            Some(ToolChoice::Tool { name }) => check_tool_name(&all_tools, name)?,
283	            _ => {}
284	        }
285	    }
286	
287	    let tool_config = assemble_tool_config(all_tools, effective_tc)?;
288	
289	    // Build InferenceConfiguration.
290	    let inference_config = build_inference_config(req, cfg);
291	
292	    Ok(PreparedConverse {
293	        model_id: cfg.model_id.clone(),
294	        system: translated.system,
295	        messages: translated.messages,
296	        tool_config,
297	        inference_config,
298	        synthesizing,
299	        output_config: None,
300	        notices: Vec::new(),
301	        tool_choice_none: false,
302	    })
303	}
304	
305	/// Translate a core [`ToolChoice`] into a Bedrock [`BedrockToolChoice`].
306	///
307	/// Returns `None` when the family does not support forced tool choice (the
308	/// `tool_choice` field is omitted from the request). `ToolChoice::None` is
309	/// handled before this function.
310	fn translate_tool_choice(tc: &ToolChoice, family: ModelFamily) -> Option<BedrockToolChoice> {
311	    match tc {
312	        ToolChoice::Auto => Some(BedrockToolChoice::Auto(AutoToolChoice::builder().build())),
313	        ToolChoice::Required => {
314	            if !family.supports_forced_tool_choice() {
315	                tracing::debug!(
316	                    target: "paigasus::bedrock::translate",
317	                    ?family,
318	                    "ToolChoice::Required requested but family does not support forced tool choice; omitting",
319	                );
320	                return None;
321	            }
322	            Some(BedrockToolChoice::Any(AnyToolChoice::builder().build()))
323	        }
324	        ToolChoice::None => {
325	            // ToolChoice::None is handled before this function; unreachable here.
326	            None
327	        }
328	        ToolChoice::Tool { name } => {
329	            if !family.supports_forced_tool_choice() {
330	                tracing::debug!(
331	                    target: "paigasus::bedrock::translate",
332	                    ?family,
333	                    tool = %name,
334	                    "ToolChoice::Tool requested but family does not support forced tool choice; omitting",
335	                );
336	                return None;
337	            }
338	            match SpecificToolChoice::builder().name(name).build() {
339	                Ok(s) => Some(BedrockToolChoice::Tool(s)),
340	                Err(e) => {
341	                    tracing::warn!(
342	                        target: "paigasus::bedrock::translate",
343	                        err = %e,
344	                        "failed to build SpecificToolChoice; omitting tool_choice",
345	                    );
346	                    None
347	                }
348	            }
349	        }
350	        _ => {
351	            tracing::debug!(
352	                target: "paigasus::bedrock::translate",
353	                "unknown ToolChoice variant; omitting",
354	            );
355	            None
356	        }
357	    }
358	}
