360	// ── Wire-projection (snapshot tests) ─────────────────────────────────────────
361	
362	/// Project a [`PreparedConverse`] into a stable [`serde_json::Value`] for
363	/// snapshot tests.
364	///
365	/// This projection is deliberately **not** based on `Debug` output of the SDK
366	/// types, which can change across SDK version bumps. Instead, it is a hand-written
367	/// extraction of the semantically relevant fields.
368	#[cfg(test)]
369	pub(crate) fn to_wire_json(p: &PreparedConverse) -> serde_json::Value {
370	    use aws_sdk_bedrockruntime::types::{
371	        ContentBlock, SystemContentBlock, ToolChoice as SdkToolChoice, ToolResultContentBlock,
372	    };
373	    use serde_json::{json, Value};
374	
375	    // System blocks
376	    let system: Vec<Value> = p
377	        .system
378	        .iter()
379	        .map(|s| match s {
380	            SystemContentBlock::Text(t) => json!({"text": t}),
381	            _ => json!({"unknown": true}),
382	        })
383	        .collect();
384	
385	    // Messages
386	    let messages: Vec<Value> = p
387	        .messages
388	        .iter()
389	        .map(|m| {
390	            let role = match m.role {
391	                aws_sdk_bedrockruntime::types::ConversationRole::User => "user",
392	                aws_sdk_bedrockruntime::types::ConversationRole::Assistant => "assistant",
393	                _ => "unknown",
394	            };
395	            let content: Vec<Value> = m
396	                .content
397	                .iter()
398	                .map(|b| match b {
399	                    ContentBlock::Text(t) => json!({"text": t}),
400	                    ContentBlock::ToolUse(tu) => json!({
401	                        "toolUse": {
402	                            "toolUseId": tu.tool_use_id,
403	                            "name": tu.name,
404	                        }
405	                    }),
406	                    ContentBlock::ToolResult(tr) => {
407	                        let text_content = tr
408	                            .content
409	                            .iter()
410	                            .find_map(|c| {
411	                                if let ToolResultContentBlock::Text(t) = c {
412	                                    Some(t.as_str())
413	                                } else {
414	                                    None
415	                                }
416	                            })
417	                            .unwrap_or("");
418	                        json!({
419	                            "toolResult": {
420	                                "toolUseId": tr.tool_use_id,
421	                                "content": [{"text": text_content}],
422	                            }
423	                        })
424	                    }
425	                    _ => json!({"unknown": true}),
426	                })
427	                .collect();
428	            json!({"role": role, "content": content})
429	        })
430	        .collect();
431	
432	    // Tool config
433	    let tool_config: Value = match &p.tool_config {
434	        None => Value::Null,
435	        Some(tc) => {
436	            let tools: Vec<Value> = tc
437	                .tools()
438	                .iter()
439	                .map(|t| match t {
440	                    Tool::ToolSpec(spec) => {
441	                        let schema_placeholder = match spec.input_schema() {
442	                            Some(s) if s.is_json() => json!("<Document>"),
443	                            _ => Value::Null,
444	                        };
445	                        json!({
446	                            "toolSpec": {
447	                                "name": spec.name(),
448	                                "description": spec.description(),
449	                                "inputSchema": {"json": schema_placeholder},
450	                            }
451	                        })
452	                    }
453	                    _ => json!({"unknown": true}),
454	                })
455	                .collect();
456	            let tc_value: Value = match tc.tool_choice() {
457	                None => Value::Null,
458	                Some(SdkToolChoice::Auto(_)) => json!({"auto": {}}),
459	                Some(SdkToolChoice::Any(_)) => json!({"any": {}}),
460	                Some(SdkToolChoice::Tool(s)) => json!({"tool": {"name": s.name()}}),
461	                _ => json!({"unknown": true}),
462	            };
463	            json!({
464	                "tools": tools,
465	                "toolChoice": tc_value,
466	            })
467	        }
468	    };
469	
470	    // Inference config
471	    let inference_config: Value = match &p.inference_config {
472	        None => Value::Null,
473	        Some(ic) => {
474	            let mut m = serde_json::Map::new();
475	            if let Some(t) = ic.temperature() {
476	                m.insert("temperature".into(), json!(t));
477	            }
478	            if let Some(p) = ic.top_p() {
479	                m.insert("topP".into(), json!(p));
480	            }
481	            if let Some(mt) = ic.max_tokens() {
482	                m.insert("maxTokens".into(), json!(mt));
483	            }
484	            Value::Object(m)
485	        }
486	    };
487	
488	    let mut wire = json!({
489	        "modelId": p.model_id,
490	        "system": system,
491	        "messages": messages,
492	        "toolConfig": tool_config,
493	        "inferenceConfig": inference_config,
494	        "synthesizing": p.synthesizing,
495	    });
496	
497	    // Extra request fields: present only when set, so the other snapshots do
498	    // not change.
499	    if p.tool_choice_none {
500	        wire["additionalModelRequestFields"] = json!({"tool_choice": {"type": "none"}});
501	    }
502	
503	    // Output config: the key is present only on the native path, so the
504	    // forced-tool snapshots do not change.
505	    if let Some(oc) = &p.output_config {
506	        let text_format = oc.text_format().map(|tf| {
507	            let structure = tf
508	                .structure()
509	                .and_then(|s| s.as_json_schema().ok())
510	                .map(|js| {
511	                    let schema: Value = serde_json::from_str(js.schema())
512	                        .expect("the native output schema is a JSON string");
513	                    json!({"jsonSchema": {"name": js.name(), "schema": schema}})
514	                });
515	            json!({"type": tf.r#type().as_str(), "structure": structure})
516	        });
517	        wire["outputConfig"] = json!({"textFormat": text_format});
518	    }
519	    wire
520	}
