524	#[cfg(test)]
525	mod tests {
526	    use super::*;
527	    use crate::translate::tools::SYNTHESIZED_TOOL_NAME;
528	    use insta::assert_json_snapshot;
529	    use paigasus_helikon_core::{
530	        ContentPart, Item, ModelRequest, ResponseFormat, ToolChoice, ToolDef,
531	    };
532	    use serde_json::json;
533	
534	    use crate::capabilities::caps_for;
535	    use crate::family::ModelFamily;
536	    use crate::policy::{ForcedChoicePolicy, NativeNotice};
537	
538	    fn make_cfg(model_id: &str) -> Config {
539	        crate::builder::offline_config(model_id)
540	    }
541	
542	    /// A minimal Config for tests — uses a Claude model so synthesis works.
543	    fn claude_cfg() -> Config {
544	        make_cfg("anthropic.claude-3-5-sonnet-20241022-v2:0")
545	    }
546	
547	    /// A Llama config for testing unsupported-family degradation.
548	    fn llama_cfg() -> Config {
549	        make_cfg("meta.llama3-1-70b-instruct-v1:0")
550	    }
551	
552	    /// Build the request on the path that the policy of `cfg` selects.
553	    fn build(cfg: &Config, req: &ModelRequest) -> Result<PreparedConverse, ModelError> {
554	        build_request(
555	            cfg,
556	            req,
557	            ForcedChoicePolicy::new(&cfg.model_id, cfg.family).path(),
558	        )
559	    }
560	
561	    /// A model that rejects a forced tool choice (the native path).
562	    fn sonnet55_cfg() -> Config {
563	        make_cfg("global.anthropic.claude-sonnet-5-5")
564	    }
565	
566	    fn assert_no_forced_choice(p: &PreparedConverse) {
567	        assert!(
568	            !p.has_forced_tool_choice(),
569	            "forced tool choice on the native path"
570	        );
571	    }
572	
573	    fn user_text(s: &str) -> Item {
574	        Item::UserMessage {
575	            content: vec![ContentPart::Text { text: s.to_owned() }],
576	        }
577	    }
578	
579	    #[test]
580	    fn build_request_rejects_trailing_blank_user() {
581	        for tool_choice in [None, Some(ToolChoice::None)] {
582	            let mut req = ModelRequest::new();
583	            req.messages = vec![
584	                user_text("q"),
585	                Item::AssistantMessage {
586	                    content: vec![ContentPart::Text {
587	                        text: "a".to_owned(),
588	                    }],
589	                    agent: None,
590	                },
591	                user_text(""),
592	            ];
593	            if let Some(tc) = tool_choice {
594	                req.model_settings.tool_choice = Some(tc);
595	            }
596	            let err = build(&claude_cfg(), &req).unwrap_err();
597	            assert!(matches!(err, ModelError::Other(_)));
598	            assert!(
599	                err.to_string()
600	                    .contains("would end with an assistant message"),
601	                "{err}"
602	            );
603	        }
604	    }
605	
606	    #[test]
607	    fn empty_messages_returns_error() {
608	        let req = ModelRequest::new();
609	        let err = build(&claude_cfg(), &req).unwrap_err();
610	        assert!(matches!(err, ModelError::Other(_)));
611	    }
612	
613	    #[test]
614	    fn plain_text_turn_no_tools() {
615	        let mut req = ModelRequest::new();
