1	//! The request on the native structured-output path.
2	//!
3	//! Some models reject a forced tool choice (`toolChoice: any` or `tool`). For
4	//! these models the provider sends a `JsonSchema` response format in
5	//! `outputConfig.textFormat` and never forces a tool call. Each change of
6	//! meaning is recorded as a [`NativeNotice`] on the result.
7	
8	use aws_sdk_bedrockruntime::types::{
9	    AutoToolChoice, JsonSchemaDefinition, OutputConfig, OutputFormat, OutputFormatStructure,
10	    OutputFormatType, Tool, ToolChoice as BedrockToolChoice,
11	};
12	use paigasus_helikon_core::{ModelError, ModelRequest, ResponseFormat, ToolChoice};
13	
14	use crate::builder::Config;
15	use crate::policy::NativeNotice;
16	use crate::translate::native_schema::native_output_schema;
17	use crate::translate::request::items_to_messages;
18	use crate::translate::response_format::synthesize;
19	use crate::translate::schema::Ruleset;
20	use crate::translate::tool_choice_none::{apply_tool_choice_none, has_tool_round};
21	use crate::translate::tools::tool_specs;
22	use crate::translate::{
23	    assemble_tool_config, build_inference_config, check_tool_name, required_without_tools_error,
24	    PreparedConverse,
25	};
26	
27	/// Assemble a [`PreparedConverse`] for the native path.
28	///
29	/// - `JsonSchema` goes to `outputConfig`. The `strict` flag has no effect.
30	/// - `JsonObject` degrades to text, because native output cannot express a
31	///   free-form object.
32	/// - `ToolChoice::Required` and `ToolChoice::Tool` are omitted. `Auto` stays.
33	/// - `ToolChoice::None` without a structured format, after a tool round: the
34	///   family strategy of `apply_tool_choice_none` decides the tools and the
35	///   history.
36	/// - After a tool round with no user tools, the synthesized tool is sent as a
37	///   `toolConfig` anchor without a `toolChoice`, because Bedrock needs a
38	///   `toolConfig` when the history holds a tool call or a tool result.
39	///
40	/// # Errors
41	/// - Reserved tool name (`__paigasus_structured_output__` used by the caller).
42	/// - `ToolChoice::Required` with no tool and no structured response format.
43	/// - `ToolChoice::Tool` with a name that is not in the tool list.
44	/// - The message errors of `items_to_messages`.
45	/// - An SDK builder error.
46	pub(crate) fn build_native(
47	    cfg: &Config,
48	    req: &ModelRequest,
49	) -> Result<PreparedConverse, ModelError> {
50	    let family = cfg.family;
51	    let ruleset = Ruleset::for_family(family);
52	    let rf = req.model_settings.response_format.as_ref();
53	    let tool_choice = req.model_settings.tool_choice.as_ref();
54	    let mut notices = Vec::new();
55	
56	    let mut translated = items_to_messages(&req.messages)?;
57	
58	    // Response format.
59	    let structured = matches!(
60	        rf,
61	        Some(ResponseFormat::JsonSchema { .. } | ResponseFormat::JsonObject)
62	    );
63	    let output_config = match rf {
64	        Some(ResponseFormat::JsonSchema { name, schema, .. }) => {
65	            Some(json_schema_output_config(name, schema)?)
66	        }
67	        Some(ResponseFormat::JsonObject) => {
68	            notices.push(NativeNotice::JsonObjectAsText);
69	            None
70	        }
71	        _ => None,
72	    };
73	
74	    // User tools. `ToolChoice::None` sends no user tools, unless the history
75	    // holds a tool round and the request is not structured. Then the family
76	    // strategy decides. A structured request keeps the anchor below.
77	    let mut tool_choice_none = false;
78	    let mut all_tools: Vec<Tool> = if matches!(tool_choice, Some(ToolChoice::None)) {
79	        if structured {
80	            Vec::new()
81	        } else {
82	            let outcome = apply_tool_choice_none(
83	                std::mem::take(&mut translated.messages),
84	                &req.tools,
85	                family,
86	                ruleset,
87	            )?;
88	            translated.messages = outcome.messages;
89	            tool_choice_none = outcome.tool_choice_none;
90	            outcome.tools
91	        }
92	    } else {
93	        tool_specs(&req.tools, ruleset)?
94	            .into_iter()
95	            .map(Tool::ToolSpec)
96	            .collect()
97	    };
98	
99	    // Check a caller-selected tool name against the user tools only. The anchor
100	    // below must not make an undefined name valid.
101	    if let Some(ToolChoice::Tool { name }) = tool_choice {
102	        check_tool_name(&all_tools, name)?;
103	    }
104	
105	    // Anchor: a structured format, no user tools and a tool round in the history.
106	    let mut synthesizing = false;
107	    if structured && all_tools.is_empty() && has_tool_round(&translated.messages) {
108	        if let Some(anchor) = synthesize(rf, family, ruleset)?.tool {
109	            all_tools.push(Tool::ToolSpec(anchor));
110	            synthesizing = true;
111	        }
112	    }
113	
114	    // Tool choice. The native path never forces a tool call.
115	    let choice = match tool_choice {
116	        None | Some(ToolChoice::None) => None,
117	        Some(ToolChoice::Auto) => Some(BedrockToolChoice::Auto(AutoToolChoice::builder().build())),
118	        Some(ToolChoice::Required) => {
119	            if all_tools.is_empty() && !structured {
120	                return Err(required_without_tools_error());
121	            }
122	            notices.push(NativeNotice::RequiredOmitted);
123	            None
124	        }
125	        Some(ToolChoice::Tool { .. }) => {
126	            notices.push(NativeNotice::ToolOmitted);
127	            None
128	        }
129	        Some(_) => {
130	            tracing::debug!(
131	                target: "paigasus::bedrock::translate",
132	                "unknown ToolChoice variant; omitting",
133	            );
134	            None
135	        }
136	    };
137	
138	    let tool_config = assemble_tool_config(all_tools, choice)?;
139	    let inference_config = build_inference_config(req, cfg);
140	
141	    Ok(PreparedConverse {
142	        model_id: cfg.model_id.clone(),
143	        system: translated.system,
144	        messages: translated.messages,
145	        tool_config,
146	        inference_config,
147	        synthesizing,
148	        output_config,
149	        notices,
150	        tool_choice_none,
151	    })
152	}
153	
154	/// Make the `outputConfig` for a `JsonSchema` response format.
155	fn json_schema_output_config(
156	    name: &str,
157	    schema: &serde_json::Value,
158	) -> Result<OutputConfig, ModelError> {
159	    let builder_error = |e| {
160	        ModelError::Other(anyhow::anyhow!(
161	            "failed to build the native output config: {e}"
162	        ))
163	    };
164	    let schema = serde_json::to_string(&native_output_schema(schema)).map_err(|e| {
165	        ModelError::Other(anyhow::anyhow!(
166	            "failed to serialize the native output schema: {e}"
167	        ))
168	    })?;
169	    let definition = JsonSchemaDefinition::builder()
170	        .schema(schema)
171	        .name(name)
172	        .build()
173	        .map_err(builder_error)?;
174	    let format = OutputFormat::builder()
175	        .r#type(OutputFormatType::JsonSchema)
176	        .structure(OutputFormatStructure::JsonSchema(definition))
177	        .build()
178	        .map_err(builder_error)?;
179	    Ok(OutputConfig::builder().text_format(format).build())
180	}
