1	//! `StreamTranslator` — Bedrock `ConverseStreamOutput` events → `ModelEvent`.
2	//!
3	//! ## Usage / Finish ordering
4	//!
5	//! The Bedrock Converse API emits events in this order:
6	//!
7	//! ```text
8	//! MessageStart
9	//! ContentBlockStart | ContentBlockDelta | ContentBlockStop  (interleaved)
10	//! MessageStop         ← stop_reason lives here
11	//! Metadata            ← usage lives here (AFTER MessageStop)
12	//! ```
13	//!
14	//! Per the `paigasus_helikon_core::Model::invoke` ordering contract,
15	//! `ModelEvent::Finish` is terminal and `ModelEvent::Usage` may appear
16	//! anywhere in the stream — most providers emit one immediately before
17	//! `Finish`. Because Bedrock emits `Metadata` (where usage lives) **after**
18	//! `MessageStop` (where the stop reason lives), this translator buffers the
19	//! stop reason when `MessageStop` arrives and emits nothing until `Metadata`
20	//! arrives — at that point it emits `Usage` immediately followed by `Finish`.
21	//!
22	//! If (contrary to the typical wire order) `Metadata` arrives **before**
23	//! `MessageStop`, `Usage` is emitted immediately on `Metadata` and `Finish`
24	//! is emitted immediately on `MessageStop`, which also satisfies the contract.
25	
26	use std::collections::HashMap;
27	
28	use aws_sdk_bedrockruntime::types::{
29	    ContentBlockDelta, ContentBlockStart, ConverseStreamOutput, ReasoningContentBlockDelta,
30	    StopReason,
31	};
32	use paigasus_helikon_core::{FinishReason, ModelError, ModelEvent};
33	
34	use crate::translate::tools::SYNTHESIZED_TOOL_NAME;
35	
36	// ── internal block state ──────────────────────────────────────────────────────
37	
38	/// Per-content-block state keyed by `content_block_index`.
39	///
40	/// Reasoning content blocks are identified purely by the
41	/// `ContentBlockDelta::ReasoningContent` delta variant; no separate block-state
42	/// entry is needed for them.
43	#[derive(Debug)]
44	enum BlockState {
45	    Text,
46	    ToolUse {
47	        call_id: String,
48	        name: String,
49	        /// `true` after the first `ToolCallDelta` has been emitted (name
50	        /// appears only in that first delta; subsequent deltas set it to
51	        /// `None`).
52	        name_emitted: bool,
53	    },
54	}
55	
56	// ── public translator ─────────────────────────────────────────────────────────
57	
58	/// State machine that maps Bedrock `ConverseStreamOutput` events to
59	/// `paigasus_helikon_core::ModelEvent`s.
60	///
61	/// Call [`StreamTranslator::consume`] once per SDK event.  The translator is
62	/// pure (no I/O) and is intended to be driven from an `async_stream!` wrapper
63	/// that feeds it chunks from `converse_stream`.
64	///
65	/// ## Synthesizing mode
66	///
67	/// When `synthesizing = true` the model was asked to fill a JSON schema via a
68	/// forced-tool call (`__paigasus_structured_output__`).  In that mode the
69	/// synthesized tool's input deltas are re-emitted as `TokenDelta`s and the
70	/// terminal `tool_use` stop reason is rewritten to `Stop`.  If a *real* tool
71	/// fires alongside the synthesized one, `ModelError::Other` is returned
72	/// (protocol violation).
73	#[derive(Debug, Default)]
74	pub struct StreamTranslator {
75	    /// `content_block_index` → per-block state.
76	    blocks: HashMap<i32, BlockState>,
77	    /// Whether we are in structured-output synthesis mode.
78	    synthesizing: bool,
79	    /// Whether the request used native structured output (`outputConfig`).
80	    native: bool,
81	    /// Whether the request set `tool_choice` to `None`. A tool call is then an error.
82	    forbid_tool_calls: bool,
83	    /// `true` once a refused tool call produced its error.
84	    refused_tool_call: bool,
85	    /// The content-block index of the synthesized tool's block (if any).
86	    synthesized_block_index: Option<i32>,
87	    /// `true` if at least one *real* (non-synthesized) tool block started.
88	    real_tool_fired: bool,
89	    /// Buffered stop reason from `MessageStop`; held until `Metadata` arrives
90	    /// so that `Usage` can be emitted first.
91	    pending_stop_reason: Option<StopReason>,
92	    /// `true` once a `Metadata` event has been processed.
93	    metadata_seen: bool,
94	}
95	
96	impl StreamTranslator {
97	    /// Create a new translator.
98	    ///
99	    /// Set `synthesizing` to `true` when the request was built with
100	    /// structured-output synthesis (forced `__paigasus_structured_output__`
101	    /// tool call).
102	    pub fn new(synthesizing: bool) -> Self {
103	        Self {
104	            synthesizing,
105	            ..Default::default()
106	        }
107	    }
108	
109	    /// Tell the translator that the request used native structured output.
110	    /// An anchor call then logs one warning, because `outputConfig` did not
111	    /// constrain the text that the anchor carries.
112	    pub(crate) fn native(mut self, native: bool) -> Self {
113	        self.native = native;
114	        self
115	    }
116	
117	    /// Tell the translator that the request set `tool_choice` to `None`.
118	    /// A tool call from the model then becomes an error.
119	    pub(crate) fn forbid_tool_calls(mut self, forbid: bool) -> Self {
120	        self.forbid_tool_calls = forbid;
121	        self
122	    }
123	
124	    /// Consume one `ConverseStreamOutput` event and return zero or more
125	    /// `ModelEvent`s (or `ModelError`s) produced by it.
126	    pub fn consume(&mut self, ev: ConverseStreamOutput) -> Vec<Result<ModelEvent, ModelError>> {
127	        let mut out: Vec<Result<ModelEvent, ModelError>> = Vec::new();
128	
129	        match ev {
130	            // ── events that produce no output ─────────────────────────────────
131	            ConverseStreamOutput::MessageStart(_) => {}
132	            ConverseStreamOutput::ContentBlockStop(_) => {}
133	
134	            // ── content block start ───────────────────────────────────────────
135	            ConverseStreamOutput::ContentBlockStart(e) => {
136	                let idx = e.content_block_index();
137	                match e.start() {
138	                    Some(ContentBlockStart::ToolUse(tu)) => {
139	                        let call_id = tu.tool_use_id().to_owned();
140	                        let name = tu.name().to_owned();
141	
142	                        if self.synthesizing && name == SYNTHESIZED_TOOL_NAME {
143	                            if self.native && self.synthesized_block_index.is_none() {
144	                                tracing::warn!(
145	                                    target: "paigasus::bedrock::stream",
146	                                    "the model called the structured-output anchor on the native path; outputConfig did not constrain this text"
147	                                );
148	                            }
149	                            self.synthesized_block_index = Some(idx);
150	                        } else if self.forbid_tool_calls {
151	                            // Record no block: its deltas then emit nothing.
152	                            // A second refused block at another index is
153	                            // silent: the error is emitted once per stream.
154	                            if !self.refused_tool_call {
155	                                self.refused_tool_call = true;
156	                                out.push(Err(ModelError::Other(anyhow::anyhow!(
157	                                    "the model called a tool, but tool_choice is None"
158	                                ))));
159	                            }
160	                            return out;
161	                        } else {
162	                            self.real_tool_fired = true;
163	                            // Emit the name-carrying delta immediately on block
164	                            // start (mirrors the Anthropic provider's behaviour
165	                            // of emitting name on the first input-json delta).
166	                            // We *don't* emit here — we wait for the first
167	                            // tool-input delta so the call_id→state map is
168	                            // consistent.
169	                        }
170	                        self.blocks.insert(
171	                            idx,
172	                            BlockState::ToolUse {
173	                                call_id,
174	                                name,
175	                                name_emitted: false,
176	                            },
177	                        );
178	                    }
179	                    Some(ContentBlockStart::Image(_) | ContentBlockStart::ToolResult(_)) => {
180	                        // Not a tool we translate; record nothing.
181	                    }
182	                    Some(_) | None => {
183	                        // Text or unknown start: record as text block.
184	                        self.blocks.insert(idx, BlockState::Text);
185	                    }
186	                }
187	            }
188	
189	            // ── content block delta ───────────────────────────────────────────
190	            ConverseStreamOutput::ContentBlockDelta(e) => {
191	                let idx = e.content_block_index();
192	                match e.delta() {
193	                    Some(ContentBlockDelta::Text(text)) => {
194	                        out.push(Ok(ModelEvent::TokenDelta { text: text.clone() }));
195	                    }
196	                    Some(ContentBlockDelta::ToolUse(tu_delta)) => {
197	                        let input = tu_delta.input().to_owned();
198	                        let is_synth = Some(idx) == self.synthesized_block_index;
199	
200	                        if is_synth {
201	                            // Remap synthesized tool input to TokenDelta.
202	                            out.push(Ok(ModelEvent::TokenDelta { text: input }));
203	                        } else if let Some(BlockState::ToolUse {
204	                            call_id,
205	                            name,
206	                            name_emitted,
207	                        }) = self.blocks.get_mut(&idx)
208	                        {
209	                            let emit_name = if *name_emitted {
210	                                None
211	                            } else {
212	                                *name_emitted = true;
213	                                Some(name.clone())
214	                            };
215	                            out.push(Ok(ModelEvent::ToolCallDelta {
216	                                call_id: call_id.clone(),
217	                                name: emit_name,
218	                                args_delta: input,
219	                            }));
220	                        }
221	                        // If no block state (shouldn't happen for well-formed
222	                        // streams), silently drop rather than panic.
223	                    }
224	                    Some(ContentBlockDelta::ReasoningContent(rc)) => match rc {
225	                        ReasoningContentBlockDelta::Text(text) => {
226	                            out.push(Ok(ModelEvent::ReasoningDelta { text: text.clone() }));
227	                        }
228	                        ReasoningContentBlockDelta::Signature(_) => {
229	                            // Signature is a round-trip token for multi-turn
230	                            // extended-thinking; we drop it here (not yet
231	                            // plumbed through the session layer).
232	                            tracing::debug!(
233	                                target: "paigasus::bedrock::stream",
234	                                "reasoning signature delta dropped (round-trip not yet supported)",
235	                            );
236	                        }
237	                        ReasoningContentBlockDelta::RedactedContent(_) => {
238	                            // Encrypted reasoning blob — provider-opaque, drop.
239	                            tracing::debug!(
240	                                target: "paigasus::bedrock::stream",
241	                                "reasoning redacted-content delta dropped",
242	                            );
243	                        }
244	                        _ => {
245	                            // Forward-compat: ignore unknown reasoning variants.
246	                        }
247	                    },
248	                    // Image, ToolResult, Citation, Unknown deltas — drop.
249	                    Some(_) | None => {}
250	                }
251	            }
252	
253	            // ── message stop (stop_reason) ────────────────────────────────────
254	            ConverseStreamOutput::MessageStop(e) => {
255	                let stop_reason = e.stop_reason().clone();
256	                if self.metadata_seen {
257	                    // Metadata already arrived; emit Finish now.
258	                    out.extend(self.finish_events(stop_reason));
259	                } else {
260	                    // Buffer; Metadata will trigger Usage + Finish.
261	                    self.pending_stop_reason = Some(stop_reason);
262	                }
263	            }
264	
265	            // ── metadata (usage) ──────────────────────────────────────────────
266	            ConverseStreamOutput::Metadata(e) => {
267	                self.metadata_seen = true;
268	                if let Some(usage) = e.usage() {
269	                    out.push(Ok(ModelEvent::Usage {
270	                        input_tokens: usage.input_tokens().max(0) as u32,
271	                        output_tokens: usage.output_tokens().max(0) as u32,
272	                        cached_input_tokens: usage
273	                            .cache_read_input_tokens()
274	                            .map(|n| n.max(0) as u32),
275	                        reasoning_tokens: None,
276	                    }));
277	                }
278	                // If a buffered stop reason is waiting, emit Finish now.
279	                if let Some(reason) = self.pending_stop_reason.take() {
280	                    out.extend(self.finish_events(reason));
281	                }
282	            }
283	
284	            // Forward-compat catch-all: Unknown and any future enum variants
285	            // added by the SDK are silently ignored.
286	            _ => {}
287	        }
288	
289	        out
290	    }
291	
292	    /// Flush any buffered stop reason when the Bedrock stream ends normally
293	    /// (EOF) without having emitted a `Metadata` event.
294	    ///
295	    /// Returns the terminal `Finish` event (or a `ModelError::Other` for the
296	    /// both-tools-fired error condition) if a stop reason is still pending,
297	    /// or `None` if the stream already emitted its terminal event through the
298	    /// normal `Metadata`→`Finish` path.
299	    ///
300	    /// **Call this only on the EOF path, not on the cancellation path.**
301	    /// Cancellation must end the stream without emitting `Finish`.
302	    pub(crate) fn finish(&mut self) -> Option<Result<ModelEvent, ModelError>> {
303	        self.pending_stop_reason
304	            .take()
305	            .and_then(|reason| self.finish_events(reason).into_iter().next())
306	    }
307	
308	    // ── private helpers ───────────────────────────────────────────────────────
309	
310	    /// Translate a `StopReason` into the terminal event(s).
311	    ///
312	    /// Returns a single `Ok(Finish{..})` in normal cases, or a single
313	    /// `Err(ModelError::Other)` when both a real and the synthesized tool
314	    /// fired in synthesis mode.
315	    fn finish_events(&self, reason: StopReason) -> Vec<Result<ModelEvent, ModelError>> {
316	        // A refused tool call already ended the stream with an error. As on the
317	        // both-tools-fired path, the error replaces the terminal `Finish`.
318	        if self.refused_tool_call {
319	            return Vec::new();
320	        }
321	        let finish = match reason {
322	            StopReason::EndTurn | StopReason::StopSequence => Ok(ModelEvent::Finish {
323	                reason: FinishReason::Stop,
324	            }),
325	            StopReason::ToolUse => {
326	                if self.synthesizing {
327	                    if self.real_tool_fired {
328	                        // Both tools fired — protocol violation.
329	                        Err(ModelError::Other(anyhow::anyhow!(
330	                            "bedrock stream: structured-output synthesis: \
331	                             model fired both a real tool and the synthesized \
332	                             output tool '__paigasus_structured_output__'"
333	                        )))
334	                    } else {
335	                        // Only synthesized tool fired — rewrite to Stop.
336	                        Ok(ModelEvent::Finish {
337	                            reason: FinishReason::Stop,
338	                        })
339	                    }
340	                } else {
341	                    Ok(ModelEvent::Finish {
342	                        reason: FinishReason::ToolCalls,
343	                    })
344	                }
345	            }
346	            StopReason::MaxTokens => Ok(ModelEvent::Finish {
347	                reason: FinishReason::Length,
348	            }),
349	            StopReason::GuardrailIntervened | StopReason::ContentFiltered => {
350	                Ok(ModelEvent::Finish {
351	                    reason: FinishReason::ContentFilter,
352	                })
353	            }
354	            other => Ok(ModelEvent::Finish {
355	                reason: FinishReason::Other(other.as_str().to_owned()),
356	            }),
357	        };
358	        vec![finish]
359	    }
360	}
