10	use async_stream::stream;
11	use async_trait::async_trait;
12	use futures_core::stream::BoxStream;
13	use paigasus_helikon_core::{
14	    CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent, ModelRequest, ToolChoice,
15	};
16	
17	use aws_sdk_bedrockruntime::operation::converse_stream::ConverseStreamOutput;
18	use aws_sdk_bedrockruntime::Client;
19	use aws_smithy_types::Document;
20	
21	use crate::builder::Config;
22	use crate::error::{map_sdk_error, send_failure, SendFailure};
23	use crate::fallback::{send_with_fallback, Sent};
24	use crate::policy::ForcedChoicePolicy;
25	use crate::stream::StreamTranslator;
