27	
28	// ── BedrockModel ──────────────────────────────────────────────────────────────
29	
30	/// An Amazon Bedrock Converse API model handle.
31	///
32	/// Construct via [`BedrockModel::converse`] (sync builder) or
33	/// [`BedrockModel::from_env`] (async, loads AWS config from the environment).
34	///
35	/// The handle is `Clone + Send + Sync` because it holds only `Arc` values.
36	/// Clones share the state that the handle learns at run time.
37	#[derive(Debug, Clone)]
38	pub struct BedrockModel {
39	    pub(crate) config: Arc<Config>,
40	    pub(crate) policy: Arc<ForcedChoicePolicy>,
41	}
42	
43	/// The `additionalModelRequestFields` document of a request, if it needs one.
44	fn additional_fields(p: &PreparedConverse) -> Option<Document> {
45	    let mut fields: HashMap<String, Document> = HashMap::new();
46	    if p.tool_choice_none {
47	        fields.insert(
48	            "tool_choice".to_owned(),
49	            Document::Object(HashMap::from([(
50	                "type".to_owned(),
51	                Document::String("none".to_owned()),
52	            )])),
53	        );
54	    }
55	    (!fields.is_empty()).then_some(Document::Object(fields))
56	}
57	
58	/// Send one `ConverseStream` request.
59	///
60	/// The error keeps the flag that tells the fallback whether the service
61	/// rejected a forced tool choice.
62	fn send_converse_stream(
63	    client: &Client,
64	    p: PreparedConverse,
65	) -> impl Future<Output = Result<ConverseStreamOutput, SendFailure>> {
66	    let additional = additional_fields(&p);
67	    let fluent = client
68	        .converse_stream()
69	        .model_id(&p.model_id)
70	        .set_messages(Some(p.messages))
71	        .set_system(if p.system.is_empty() {
72	            None
73	        } else {
74	            Some(p.system)
75	        })
76	        .set_tool_config(p.tool_config)
77	        .set_inference_config(p.inference_config)
78	        .set_output_config(p.output_config)
79	        .set_additional_model_request_fields(additional);
80	    // fluent.send() returns SdkError<_, HttpResponse>, so send_failure can
81	    // read the Retry-After header.
82	    async move { fluent.send().await.map_err(send_failure) }
83	}
84	
85	// ── Model impl ────────────────────────────────────────────────────────────────
86	
87	#[async_trait]
88	impl Model for BedrockModel {
89	    /// Stream model events from Amazon Bedrock's Converse API.
90	    ///
91	    /// The returned stream is `'static + Send`.
92	    ///
93	    /// **Cancellation contract:** when `cancel` fires mid-stream, the stream
94	    /// ends immediately without emitting a final `Finish` event (per the core
95	    /// `Model` trait contract).
96	    async fn invoke(
97	        &self,
98	        request: ModelRequest,
99	        cancel: CancellationToken,
100	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
101	        // Translate the core request into Bedrock wire format (early error on
102	        // translation failure — before we open any network connection).
103	        let first = build_request(&self.config, &request, self.policy.path())?;
104	
105	        let forbid = matches!(request.model_settings.tool_choice, Some(ToolChoice::None));
106	        let config = Arc::clone(&self.config);
107	        let policy = Arc::clone(&self.policy);
108	        let client = self.config.client.clone();
109	
110	        let s = stream! {
111	            // The rebuild closure owns the request. It makes the native
112	            // request if the service rejects the forced tool choice of the
113	            // first request.
114	            let rebuild_cfg = Arc::clone(&config);
115	            let rebuild = move |path| build_request(&rebuild_cfg, &request, path);
116	
117	            // Send the request (and the one fallback request, if any) and
118	            // obtain the event receiver. Guard with a cancellation check
119	            // (biased: cancel arm wins) so that a token already fired — or one
120	            // that fires during either HTTP send — aborts cleanly without
121	            // opening a dangling Bedrock stream and without emitting Finish
122	            // (per the Model::invoke cancellation contract).
123	            let sent = tokio::select! {
124	                biased;
125	                _ = cancel.cancelled() => { return; }
126	                result = send_with_fallback(
127	                    &policy,
128	                    &config.model_id,
129	                    first,
130	                    rebuild,
131	                    |p| send_converse_stream(&client, p),
132	                ) => result,
133	            };
134	            let Sent {
135	                output,
136	                synthesizing,
137	                native,
138	            } = match sent {
139	                Ok(sent) => sent,
140	                Err(e) => {
141	                    yield Err(e);
142	                    return;
143	                }
144	            };
145	
146	            let mut receiver = output.stream;
147	            let mut translator = StreamTranslator::new(synthesizing)
148	                .native(native)
149	                .forbid_tool_calls(forbid);
150	
151	            loop {
152	                let next = tokio::select! {
153	                    biased;
154	                    _ = cancel.cancelled() => {
155	                        // Cancellation: end stream without emitting Finish.
156	                        return;
157	                    }
158	                    r = receiver.recv() => r,
159	                };
160	
161	                match next {
162	                    // Stream exhausted normally (EOF).
163	                    // Flush any buffered stop reason that arrived without a
164	                    // subsequent Metadata event so the consumer always sees
165	                    // a terminal Finish.
166	                    Ok(None) => {
167	                        if let Some(terminal) = translator.finish() {
168	                            yield terminal;
169	                        }
170	                        return;
171	                    }
172	                    // Good event — feed through translator and yield results.
173	                    Ok(Some(event)) => {
174	                        for result in translator.consume(event) {
175	                            yield result;
176	                        }
177	                    }
178	                    // Transport-level error on the event stream.
179	                    Err(e) => {
180	                        yield Err(map_sdk_error(e));
181	                        return;
182	                    }
183	                }
184	            }
185	        };
186	
187	        Ok(Box::pin(s))
188	    }
189	
190	    fn capabilities(&self) -> ModelCapabilities {
191	        self.config.capabilities
192	    }
193	
194	    fn provider(&self) -> &str {
195	        "bedrock"
196	    }
197	
198	    fn model(&self) -> &str {
199	        &self.config.model_id
200	    }
201	}
