329	    // ── Cancellation contract tests ───────────────────────────────────────────
330	
331	    use futures_core::Stream;
332	    use futures_util::StreamExt;
333	
334	    /// Build a stream that yields `n` `TokenDelta` events then ends.
335	    fn token_stream(
336	        n: usize,
337	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
338	        let events: Vec<Result<ModelEvent, ModelError>> = (0..n)
339	            .map(|i| {
340	                Ok(ModelEvent::TokenDelta {
341	                    text: format!("chunk-{i}"),
342	                })
343	            })
344	            .collect();
345	        futures_util::stream::iter(events)
346	    }
347	
348	    /// Build a stream that yields `n` `TokenDelta` events then a `Finish` event.
349	    fn token_stream_with_finish(
350	        n: usize,
351	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
352	        use paigasus_helikon_core::FinishReason;
353	        let mut events: Vec<Result<ModelEvent, ModelError>> = (0..n)
354	            .map(|i| {
355	                Ok(ModelEvent::TokenDelta {
356	                    text: format!("chunk-{i}"),
357	                })
358	            })
359	            .collect();
360	        events.push(Ok(ModelEvent::Finish {
361	            reason: FinishReason::Stop,
362	        }));
363	        futures_util::stream::iter(events)
364	    }
365	
366	    #[tokio::test]
367	    async fn cancel_before_stream_ends_no_finish() {
368	        let cancel = CancellationToken::new();
369	        let source = token_stream(10);
370	
371	        // Cancel immediately — the stream should yield 0 events and no Finish.
372	        cancel.cancel();
373	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
374	
375	        let has_finish = events
376	            .iter()
377	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
378	        assert!(!has_finish, "cancelled stream must not emit Finish");
379	    }
