416	    #[tokio::test]
417	    async fn uncancelled_stream_emits_finish() {
418	        let cancel = CancellationToken::new();
419	        let source = token_stream_with_finish(3);
420	
421	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
422	
423	        let has_finish = events
424	            .iter()
425	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
426	        assert!(has_finish, "uncancelled stream must emit Finish");
427	        // All 3 token deltas + finish = 4 events.
428	        assert_eq!(events.len(), 4, "expected 3 tokens + 1 finish");
429	    }
