431	    #[tokio::test]
432	    async fn cancel_does_not_drop_events_already_yielded() {
433	        let cancel = CancellationToken::new();
434	        // 5 events, no finish.  Don't cancel — all should arrive.
435	        let source = token_stream(5);
436	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
437	        assert_eq!(events.len(), 5, "all events must arrive when not cancelled");
438	    }
