440	    /// Live test for the learned native path (rule B), with rule A off.
441	    ///
442	    /// Run it only with `BEDROCK_MODEL_ID=global.anthropic.claude-sonnet-5-5`
443	    /// and `cargo test -p paigasus-helikon-providers-bedrock
444	    /// live_rule_b -- --ignored --nocapture`.
445	    #[tokio::test]
446	    #[ignore]
447	    async fn live_rule_b_learns_native_output_after_rejection() {
448	        use crate::policy::{ForcedChoicePolicy, OutputPath};
449	        use paigasus_helikon_core::{ContentPart, Item, ResponseFormat};
450	
451	        let id = match std::env::var("BEDROCK_MODEL_ID") {
452	            Ok(v) if !v.is_empty() => v,
453	            _ => {
454	                eprintln!("[live] BEDROCK_MODEL_ID not set - skipping rule B live test.");
455	                return;
