459	        if family != crate::ModelFamily::Anthropic {
460	            eprintln!("[live] {id} is not an Anthropic model - skipping");
461	            return;
462	        }
463	        let mut model = BedrockModel::from_env(&id).await.expect("from_env");
464	        model.policy = Arc::new(ForcedChoicePolicy::without_static_rule(family));
465	        assert_eq!(model.policy.path(), OutputPath::ForcedTool);
466	
467	        let mut req = ModelRequest::new();
468	        req.messages = vec![Item::UserMessage {
469	            content: vec![ContentPart::Text {
470	                text: "Give a transaction: deposit of 100 USD.".to_owned(),
471	            }],
472	        }];
473	        req.model_settings.response_format = Some(ResponseFormat::JsonSchema {
474	            name: "Transaction".to_owned(),
475	            schema: serde_json::json!({
476	                "type": "object",
477	                "properties": {
478	                    "operation": { "type": "string" },
479	                    "amount": { "type": "number" }
480	                },
481	                "required": ["operation", "amount"]
482	            }),
