493	            if let ModelEvent::TokenDelta { text: t } = ev.expect("no stream error") {
494	                text.push_str(&t);
495	            }
496	        }
497	        assert_eq!(
498	            model.policy.path(),
499	            OutputPath::Native,
500	            "one classified rejection must set the learned flag"
501	        );
