    #[test]
    fn rejection_falls_back_once_to_native() {
        let cfg = offline_config(CLAUDE);
        let policy = ForcedChoicePolicy::without_static_rule(ModelFamily::Anthropic);
        let (res, wires) = drive(
            &policy,
