213	    /// Wrap any `Stream<Item = Result<ModelEvent, ModelError>>` with a
214	    /// `CancellationToken` guard.
215	    ///
216	    /// When `cancel` fires, the returned stream ends immediately **without**
217	    /// emitting a `Finish` event — matching the `Model::invoke` cancellation
218	    /// contract.
219	    fn drive_stream_with_token<S>(
220	        source: S,
221	        cancel: CancellationToken,
222	    ) -> BoxStream<'static, Result<ModelEvent, ModelError>>
223	    where
224	        S: futures_core::Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static,
225	    {
226	        Box::pin(stream! {
227	            tokio::pin!(source);
228	            loop {
229	                let next = tokio::select! {
230	                    biased;
231	                    _ = cancel.cancelled() => return,
232	                    r = futures_util::StreamExt::next(&mut source) => r,
233	                };
234	                match next {
235	                    None => return,
236	                    Some(v) => yield v,
237	                }
238	            }
239	        })
240	    }
