348	    /// Build a stream that yields `n` `TokenDelta` events then a `Finish` event.
349	    fn token_stream_with_finish(
350	        n: usize,
351	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
352	        use paigasus_helikon_core::FinishReason;
353	        let mut events: Vec<Result<ModelEvent, ModelError>> = (0..n)
354	            .map(|i| {
355	                Ok(ModelEvent::TokenDelta {
356	                    text: format!("chunk-{i}"),
357	                })
358	            })
359	            .collect();
360	        events.push(Ok(ModelEvent::Finish {
361	            reason: FinishReason::Stop,
362	        }));
363	        futures_util::stream::iter(events)
364	    }
