383	        use std::sync::atomic::{AtomicBool, Ordering};
384	        use std::sync::Arc;
385	
386	        let cancel = CancellationToken::new();
387	        let cancel_clone = cancel.clone();
388	
389	        // A stream that cancels itself after yielding the first token.
390	        let cancelled = Arc::new(AtomicBool::new(false));
391	        let cancelled_clone = cancelled.clone();
392	
393	        let source = async_stream::stream! {
394	            yield Ok::<ModelEvent, ModelError>(ModelEvent::TokenDelta { text: "first".to_owned() });
395	            // Signal cancellation after the first token.
396	            if !cancelled_clone.swap(true, Ordering::SeqCst) {
397	                cancel_clone.cancel();
398	            }
399	            // `biased;` in drive_stream_with_token's tokio::select! checks the
400	            // cancel arm first on every iteration, so once cancel() fires the
401	            // driver exits before polling the source again — making this
402	            // single-threaded ordering deterministic and guaranteeing no Finish
403	            // is emitted after cancel.
404	            yield Ok(ModelEvent::TokenDelta { text: "second".to_owned() });
405	            yield Ok(ModelEvent::Finish { reason: paigasus_helikon_core::FinishReason::Stop });
406	        };
