555	            .invoke(req, CancellationToken::new())
556	            .await
557	            .expect("invoke should succeed");
558	        let mut text = String::new();
559	        while let Some(ev) = s.next().await {
560	            if let ModelEvent::TokenDelta { text: t } = ev.expect("no stream error") {
561	                text.push_str(&t);
562	            }
563	        }
564	        let v: serde_json::Value = serde_json::from_str(&text)
565	            .unwrap_or_else(|e| panic!("output must be valid JSON ({e}); got: {text}"));
566	        assert!(v["operation"].is_string(), "operation: {v}");
567	        eprintln!("[live] final output path: {:?}", model.policy.path());
568	    }
