1	//! The single send fallback for a forced tool choice that the service rejects.
2	//!
3	//! An Anthropic model on Bedrock can reject a forced tool choice
4	//! (`toolChoice` `any` or `tool`) with a `ValidationException`. When the
5	//! first request carried a forced choice and the service rejects it before
6	//! the stream starts, the provider sends one native request, which is a
7	//! different request, on the structured-output path. The handle then records the rejection, and
8	//! all later requests on the handle use the native path at once.
9	//!
10	//! This fallback does not break ADR-10 (*No silent auto-retry inside the
11	//! loop*), for four reasons. The fallback sends a *different* request, not
12	//! the same request again. It occurs at most once for each request. It is
13	//! logged. It never follows a transient error (throttling, a 5xx error or a
14	//! transport error): those errors go to the caller unchanged.
15	//!
16	//! The match on the error text is a weak contract. If Bedrock changes the
17	//! text, the result is the same `ValidationException` as before this
18	//! fallback existed. The static model-id rule still sends the known models
19	//! on the native path from the first request.
20	
21	use std::future::Future;
22	
23	use paigasus_helikon_core::ModelError;
24	
25	use crate::error::SendFailure;
26	use crate::family::ModelFamily;
27	use crate::policy::{ForcedChoicePolicy, OutputPath};
28	use crate::translate::PreparedConverse;
29	
30	/// The output of a send, with the `synthesizing` value of the request that
31	/// was actually sent.
32	#[derive(Debug)]
33	pub(crate) struct Sent<T> {
34	    /// The output of the send.
35	    pub(crate) output: T,
36	    /// `synthesizing` of the request that was sent.
37	    pub(crate) synthesizing: bool,
38	    /// `true` when the request that was sent used native structured output.
39	    pub(crate) native: bool,
40	}
41	
42	/// Send `first`. If the service rejects its forced tool choice, send the
43	/// request again on the native path, one time.
44	///
45	/// The fallback occurs only when all of these conditions are true:
46	/// the model family is Anthropic, `first` carried a forced tool choice, and
47	/// the failure is a rejection of that choice. `rebuild` makes the native
48	/// request. An error from the second send goes to the caller with no
49	/// further fallback.
50	pub(crate) async fn send_with_fallback<T, B, S, Fut>(
51	    policy: &ForcedChoicePolicy,
52	    model_id: &str,
53	    first: PreparedConverse,
54	    rebuild: B,
55	    mut send: S,
56	) -> Result<Sent<T>, ModelError>
57	where
58	    B: FnOnce(OutputPath) -> Result<PreparedConverse, ModelError>,
59	    S: FnMut(PreparedConverse) -> Fut,
60	    Fut: Future<Output = Result<T, SendFailure>>,
61	{
62	    for n in &first.notices {
63	        policy.note(*n, model_id);
64	    }
65	    let synthesizing = first.synthesizing;
66	    let native = first.output_config.is_some();
67	    let first_was_forced = first.has_forced_tool_choice();
68	
69	    let failure = match send(first).await {
70	        Ok(output) => {
71	            return Ok(Sent {
72	                output,
73	                synthesizing,
74	                native,
75	            })
76	        }
77	        Err(f) => f,
78	    };
79	
80	    if !(policy.family() == ModelFamily::Anthropic
81	        && first_was_forced
82	        && failure.forced_choice_rejected)
83	    {
84	        return Err(failure.error);
85	    }
86	
87	    if policy.record_rejection() {
88	        tracing::warn!(
89	            target: "paigasus::bedrock::model",
90	            model_id = %model_id,
91	            "the model rejected a forced tool choice; native structured output is now in use for this handle"
92	        );
93	    }
94	
95	    let second = rebuild(OutputPath::Native)?;
96	    for n in &second.notices {
97	        policy.note(*n, model_id);
98	    }
99	    let synthesizing = second.synthesizing;
100	    let native = second.output_config.is_some();
101	    match send(second).await {
102	        Ok(output) => Ok(Sent {
103	            output,
104	            synthesizing,
105	            native,
106	        }),
107	        Err(f) => Err(f.error),
108	    }
109	}
