1	//! Handling of `ToolChoice::None` when the history holds a tool round.
2	//!
3	//! Converse rejects a history with `toolUse` or `toolResult` blocks unless the
4	//! request has a `toolConfig`. Each model family has its own strategy, chosen
5	//! by [`ModelFamily::tool_choice_none_strategy`].
6	
7	use std::collections::HashSet;
8	
9	use aws_sdk_bedrockruntime::types::{
10	    ContentBlock, Message, Tool, ToolInputSchema, ToolResultContentBlock, ToolSpecification,
11	};
12	use paigasus_helikon_core::{ModelError, ToolDef};
13	use serde_json::json;
14	
15	use crate::document::{document_to_value, value_to_document};
16	use crate::family::{ModelFamily, ToolChoiceNoneStrategy};
17	use crate::translate::schema::Ruleset;
18	use crate::translate::tools::tool_specs;
19	
20	/// Description of a tool spec that is derived from the history.
21	const DERIVED_DESCRIPTION: &str = "A tool that this conversation used earlier.";
22	
23	/// Returns `true` when a message holds a tool call or a tool result.
24	pub(crate) fn has_tool_round(messages: &[Message]) -> bool {
25	    messages.iter().any(|m| {
26	        m.content()
27	            .iter()
28	            .any(|b| matches!(b, ContentBlock::ToolUse(_) | ContentBlock::ToolResult(_)))
29	    })
30	}
31	
32	/// The result of [`apply_tool_choice_none`].
33	#[derive(Debug)]
34	pub(crate) struct NoneOutcome {
35	    /// The messages to send.
36	    pub(crate) messages: Vec<Message>,
37	    /// The tools for the `toolConfig`. Empty when no `toolConfig` is needed.
38	    pub(crate) tools: Vec<Tool>,
39	    /// `true` when the request must carry `tool_choice: {"type": "none"}`.
40	    pub(crate) tool_choice_none: bool,
41	}
42	
43	fn unchanged(messages: Vec<Message>) -> NoneOutcome {
44	    NoneOutcome {
45	        messages,
46	        tools: Vec::new(),
47	        tool_choice_none: false,
48	    }
49	}
50	
51	/// Apply `ToolChoice::None` to the messages and tools, per model family.
52	///
53	/// - No tool round: nothing changes.
54	/// - `AnthropicNoneField`: the `toolConfig` holds the user tools and one
55	///   derived spec for each tool name in the history that is not yet listed.
56	///   The request must then carry the `tool_choice` none field.
57	/// - `TextHistory`: each tool block becomes a text block.
58	///
59	/// # Errors
60	/// The errors of [`tool_specs`], when the history holds a tool round.
61	pub(crate) fn apply_tool_choice_none(
62	    messages: Vec<Message>,
63	    user_tools: &[ToolDef],
64	    family: ModelFamily,
65	    ruleset: Ruleset,
66	) -> Result<NoneOutcome, ModelError> {
67	    if !has_tool_round(&messages) {
68	        return Ok(unchanged(messages));
69	    }
70	    match family.tool_choice_none_strategy() {
71	        ToolChoiceNoneStrategy::AnthropicNoneField => {
72	            let mut specs = tool_specs(user_tools, ruleset)?;
73	            let mut seen: HashSet<String> = specs.iter().map(|s| s.name().to_owned()).collect();
74	            for message in &messages {
75	                for block in message.content() {
76	                    let ContentBlock::ToolUse(tu) = block else {
77	                        continue;
78	                    };
79	                    if !seen.insert(tu.name().to_owned()) {
80	                        continue;
81	                    }
82	                    match derived_spec(tu.name()) {
83	                        Ok(spec) => specs.push(spec),
84	                        Err(e) => tracing::debug!(
85	                            target: "paigasus::bedrock::translate",
86	                            name = tu.name(),
87	                            error = %e,
88	                            "skipping a history tool name that the spec builder refuses",
89	                        ),
90	                    }
91	                }
92	            }
93	            if specs.is_empty() {
94	                return Ok(unchanged(messages));
95	            }
96	            Ok(NoneOutcome {
97	                messages,
98	                tools: specs.into_iter().map(Tool::ToolSpec).collect(),
99	                tool_choice_none: true,
100	            })
101	        }
102	        ToolChoiceNoneStrategy::TextHistory => {
103	            let (messages, changed) = history_as_text(messages);
104	            if changed {
105	                tracing::debug!(
106	                    target: "paigasus::bedrock::translate",
107	                    "tool_choice none: replayed the tool history as text",
108	                );
109	            }
110	            Ok(unchanged(messages))
111	        }
112	    }
113	}
114	
115	/// Build a spec for a tool name from the history.
116	fn derived_spec(
117	    name: &str,
118	) -> Result<ToolSpecification, aws_smithy_types::error::operation::BuildError> {
119	    ToolSpecification::builder()
120	        .name(name)
121	        .description(DERIVED_DESCRIPTION)
122	        .input_schema(ToolInputSchema::Json(value_to_document(
123	            &json!({"type": "object"}),
124	        )))
125	        .build()
126	}
127	
128	/// Replace each tool block with a text block. Returns the flag "changed".
129	fn history_as_text(messages: Vec<Message>) -> (Vec<Message>, bool) {
130	    let mut changed = false;
131	    let out = messages
132	        .into_iter()
133	        .map(|m| {
134	            let blocks: Vec<ContentBlock> = m
135	                .content()
136	                .iter()
137	                .map(|b| match b {
138	                    ContentBlock::ToolUse(tu) => {
139	                        changed = true;
140	                        let input = serde_json::to_string(&document_to_value(tu.input()))
141	                            .unwrap_or_else(|_| "null".to_owned());
142	                        ContentBlock::Text(format!(
143	                            "[tool call {}: {} {}]",
144	                            tu.tool_use_id(),
145	                            tu.name(),
146	                            input
147	                        ))
148	                    }
149	                    ContentBlock::ToolResult(tr) => {
150	                        changed = true;
151	                        let text = tr
152	                            .content()
153	                            .iter()
154	                            .filter_map(|c| match c {
155	                                ToolResultContentBlock::Text(t) => Some(t.as_str()),
156	                                _ => None,
157	                            })
158	                            .collect::<Vec<_>>()
159	                            .join("\n");
160	                        let quoted =
161	                            serde_json::to_string(&text).unwrap_or_else(|_| "\"\"".to_owned());
162	                        ContentBlock::Text(format!(
163	                            "[tool result {}: {}]",
164	                            tr.tool_use_id(),
165	                            quoted
166	                        ))
167	                    }
168	                    other => other.clone(),
169	                })
170	                .collect();
171	            Message::builder()
172	                .role(m.role().clone())
173	                .set_content(Some(blocks))
174	                .build()
175	                .unwrap_or(m)
176	        })
177	        .collect();
178	    (out, changed)
179	}
