118	) -> Result<ToolSpecification, aws_smithy_types::error::operation::BuildError> {
119	    ToolSpecification::builder()
120	        .name(name)
121	        .description(DERIVED_DESCRIPTION)
122	        .input_schema(ToolInputSchema::Json(value_to_document(
123	            &json!({"type": "object"}),
124	        )))
125	        .build()
126	}
