128	/// Replace each tool block with a text block. Returns the flag "changed".
129	fn history_as_text(messages: Vec<Message>) -> (Vec<Message>, bool) {
130	    let mut changed = false;
131	    let out = messages
132	        .into_iter()
133	        .map(|m| {
134	            let blocks: Vec<ContentBlock> = m
135	                .content()
136	                .iter()
137	                .map(|b| match b {
138	                    ContentBlock::ToolUse(tu) => {
139	                        changed = true;
140	                        let input = serde_json::to_string(&document_to_value(tu.input()))
141	                            .unwrap_or_else(|_| "null".to_owned());
142	                        ContentBlock::Text(format!(
143	                            "[tool call {}: {} {}]",
144	                            tu.tool_use_id(),
145	                            tu.name(),
146	                            input
147	                        ))
148	                    }
149	                    ContentBlock::ToolResult(tr) => {
150	                        changed = true;
151	                        let text = tr
152	                            .content()
153	                            .iter()
154	                            .filter_map(|c| match c {
155	                                ToolResultContentBlock::Text(t) => Some(t.as_str()),
156	                                _ => None,
157	                            })
158	                            .collect::<Vec<_>>()
159	                            .join("\n");
160	                        let quoted =
161	                            serde_json::to_string(&text).unwrap_or_else(|_| "\"\"".to_owned());
162	                        ContentBlock::Text(format!(
163	                            "[tool result {}: {}]",
164	                            tr.tool_use_id(),
165	                            quoted
166	                        ))
167	                    }
168	                    other => other.clone(),
169	                })
170	                .collect();
171	            Message::builder()
172	                .role(m.role().clone())
173	                .set_content(Some(blocks))
174	                .build()
175	                .unwrap_or(m)
176	        })
177	        .collect();
178	    (out, changed)
179	}
