1	//! `ToolDef` → Bedrock `ToolSpecification` translation.
2	//!
3	//! Each `ToolDef.schema` is run through `rewrite_tool_schema` before being
4	//! converted to a Smithy `Document` via `value_to_document`.
5	
6	use aws_sdk_bedrockruntime::types::{ToolInputSchema, ToolSpecification};
7	use paigasus_helikon_core::{ModelError, ToolDef};
8	
9	use crate::document::value_to_document;
10	use crate::translate::schema::{rewrite_tool_schema, Ruleset};
11	
12	/// Reserved tool name used internally for structured-output synthesis.
13	///
14	/// User-provided tools with this name are rejected to avoid collisions.
15	pub const SYNTHESIZED_TOOL_NAME: &str = "__paigasus_structured_output__";
16	
17	/// Translate a slice of [`ToolDef`]s into Bedrock [`ToolSpecification`]s.
18	///
19	/// # Errors
20	/// Returns [`ModelError::Other`] when any tool name equals
21	/// [`SYNTHESIZED_TOOL_NAME`] (reserved for structured-output synthesis).
22	pub(crate) fn tool_specs(
23	    defs: &[ToolDef],
24	    ruleset: Ruleset,
25	) -> Result<Vec<ToolSpecification>, ModelError> {
26	    let mut specs = Vec::with_capacity(defs.len());
27	    for def in defs {
28	        if def.name == SYNTHESIZED_TOOL_NAME {
29	            return Err(ModelError::Other(anyhow::anyhow!(
30	                "tool name '{SYNTHESIZED_TOOL_NAME}' is reserved by the Bedrock provider \
31	                 for structured-output synthesis",
32	            )));
33	        }
34	        let rewritten = rewrite_tool_schema(&def.schema, ruleset);
35	        let doc = value_to_document(&rewritten);
36	        let spec = ToolSpecification::builder()
37	            .name(&def.name)
38	            .description(&def.description)
39	            .input_schema(ToolInputSchema::Json(doc))
40	            .build()
41	            .map_err(|e| {
42	                ModelError::Other(anyhow::anyhow!("failed to build ToolSpecification: {e}"))
43	            })?;
44	        specs.push(spec);
45	    }
46	    Ok(specs)
47	}
48	
49	// ── Unit tests ────────────────────────────────────────────────────────────────
50	
51	#[cfg(test)]
52	mod tests {
53	    use super::*;
54	    use serde_json::json;
55	
56	    fn simple_def(name: &str) -> ToolDef {
57	        ToolDef::new(
58	            name,
59	            "a tool",
60	            json!({"type": "object", "properties": {"x": {"type": "string"}}}),
61	        )
62	    }
63	
64	    #[test]
65	    fn empty_defs_returns_empty_vec() {
66	        let specs = tool_specs(&[], Ruleset::Strict).unwrap();
67	        assert!(specs.is_empty());
68	    }
69	
70	    #[test]
71	    fn translates_name_and_description() {
72	        let defs = vec![simple_def("search")];
73	        let specs = tool_specs(&defs, Ruleset::Strict).unwrap();
74	        assert_eq!(specs.len(), 1);
75	        assert_eq!(specs[0].name(), "search");
76	        assert_eq!(specs[0].description(), Some("a tool"));
77	    }
78	
79	    #[test]
80	    fn schema_becomes_json_input_schema() {
81	        let defs = vec![simple_def("ping")];
82	        let specs = tool_specs(&defs, Ruleset::Strict).unwrap();
83	        assert!(specs[0].input_schema().is_some());
84	        assert!(specs[0].input_schema().unwrap().is_json());
85	    }
86	
87	    #[test]
88	    fn reserved_name_returns_error() {
89	        let defs = vec![ToolDef::new(SYNTHESIZED_TOOL_NAME, "bad", json!({}))];
90	        let err = tool_specs(&defs, Ruleset::Strict).unwrap_err();
91	        assert!(matches!(err, ModelError::Other(_)));
92	        let msg = format!("{err}");
93	        assert!(msg.contains("reserved"));
94	    }
95	
96	    #[test]
97	    fn schema_rewriter_strips_unsupported_keywords() {
98	        // $schema should be stripped by the Strict rewriter.
99	        let defs = vec![ToolDef::new(
100	            "foo",
101	            "",
102	            json!({
103	                "$schema": "http://json-schema.org/draft-07/schema#",
104	                "type": "object",
105	                "properties": {"n": {"type": "integer"}}
106	            }),
