43	        )
44	    }
45	
46	    /// Make a policy with no static rule.
47	    #[cfg(test)]
48	    pub(crate) fn without_static_rule(family: ModelFamily) -> Self {
49	        Self::with_rule(false, family)
50	    }
51	
52	    fn with_rule(rejects_static: bool, family: ModelFamily) -> Self {
53	        Self {
54	            rejects_static,
55	            learned: AtomicBool::new(false),
56	            family,
57	            warned: [
58	                AtomicBool::new(false),
59	                AtomicBool::new(false),
60	                AtomicBool::new(false),
61	            ],
62	        }
63	    }
64	
65	    /// The model family of this handle.
66	    pub(crate) fn family(&self) -> ModelFamily {
67	        self.family
68	    }
69	
70	    /// The output path for the next request.
71	    pub(crate) fn path(&self) -> OutputPath {
72	        if self.rejects_static || self.learned.load(Ordering::SeqCst) {
73	            OutputPath::Native
74	        } else {
75	            OutputPath::ForcedTool
76	        }
77	    }
78	
79	    /// Record that the service rejected a forced tool choice. Returns `true` only for the first call.
80	    pub(crate) fn record_rejection(&self) -> bool {
81	        !self.learned.swap(true, Ordering::SeqCst)
82	    }
83	
84	    /// Returns `true` only the first time for each notice kind.
85	    pub(crate) fn first_notice(&self, n: NativeNotice) -> bool {
86	        !self.warned[n as usize].swap(true, Ordering::SeqCst)
87	    }
88	
89	    /// Log the notice once per handle.
90	    pub(crate) fn note(&self, n: NativeNotice, model_id: &str) {
91	        if !self.first_notice(n) {
92	            return;
93	        }
94	        let text = match n {
95	            NativeNotice::RequiredOmitted => {
96	                "ToolChoice::Required is omitted: this model rejects a forced tool choice"
97	            }
98	            NativeNotice::ToolOmitted => {
99	                "ToolChoice::Tool is omitted: this model rejects a forced tool choice"
100	            }
101	            NativeNotice::JsonObjectAsText => {
102	                "ResponseFormat::JsonObject degrades to text: native output cannot express a free-form object"
103	            }
104	        };
105	        tracing::warn!(target: "paigasus::bedrock::translate", model_id = %model_id, "{text}");
106	    }
107	}
