109	#[cfg(test)]
110	mod tests {
111	    use super::*;
112	    use ModelFamily::Anthropic;
113	
114	    #[test]
115	    fn path_for_each_combination() {
116	        assert_eq!(
117	            ForcedChoicePolicy::new("global.anthropic.claude-sonnet-5-5", Anthropic).path(),
118	            OutputPath::Native
119	        );
120	        assert_eq!(
121	            ForcedChoicePolicy::new("global.anthropic.claude-sonnet-5", Anthropic).path(),
122	            OutputPath::ForcedTool
123	        );
124	        let p = ForcedChoicePolicy::without_static_rule(Anthropic);
125	        assert_eq!(p.path(), OutputPath::ForcedTool);
126	        assert!(p.record_rejection());
127	        assert_eq!(p.path(), OutputPath::Native);
128	        let both = ForcedChoicePolicy::new("us.anthropic.claude-opus-5-5", Anthropic);
129	        both.record_rejection();
130	        assert_eq!(both.path(), OutputPath::Native);
131	    }
132	
133	    #[test]
134	    fn record_rejection_is_true_only_once_across_threads() {
135	        let p = std::sync::Arc::new(ForcedChoicePolicy::without_static_rule(Anthropic));
136	        let firsts: usize = (0..8)
137	            .map(|_| {
138	                let p = p.clone();
139	                std::thread::spawn(move || p.record_rejection())
140	            })
141	            .collect::<Vec<_>>()
142	            .into_iter()
143	            .map(|h| h.join().unwrap() as usize)
144	            .sum();
145	        assert_eq!(firsts, 1);
146	    }
147	
148	    #[test]
149	    fn first_notice_is_true_once_per_kind() {
150	        let p = ForcedChoicePolicy::without_static_rule(Anthropic);
151	        assert!(p.first_notice(NativeNotice::RequiredOmitted));
152	        assert!(!p.first_notice(NativeNotice::RequiredOmitted));
153	        assert!(p.first_notice(NativeNotice::ToolOmitted));
154	        assert!(p.first_notice(NativeNotice::JsonObjectAsText));
155	    }
156	}
